/**
 * End-user portal visibility rules for service providers (amfa-444).
 *
 * An SP is shown to a user when it is released AND either it names no user
 * groups or the user belongs to at least one of them. An empty/absent group
 * list keeps the pre-444 behaviour (everyone sees it), so existing SPs need
 * no migration. This is a display filter only, not an access control.
 */

/**
 * Parse the `groups` value the multi-tenant authorizer puts in the request
 * context: a JSON-encoded array of Cognito group names.
 * @param {unknown} raw
 * @returns {string[]}
 */
export function parseUserGroups(raw) {
  if (Array.isArray(raw)) return raw.filter(g => typeof g === 'string');
  if (typeof raw !== 'string' || raw === '') return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter(g => typeof g === 'string') : [];
  } catch {
    return [];
  }
}

/**
 * @param {{released?: boolean, groups?: unknown}} sp
 * @param {string[]} userGroups
 * @returns {boolean}
 */
export function visibleTo(sp, userGroups) {
  if (!sp?.released) return false;
  const spGroups = Array.isArray(sp.groups) ? sp.groups.filter(g => typeof g === 'string') : [];
  if (spGroups.length === 0) return true;
  return spGroups.some(g => userGroups.includes(g));
}
